try {
  const out = [];
  const now = new Date().toISOString();
  var hostMap = { "www.theguardian.com": "The Guardian AI", "www.technologyreview.com": "MIT Technology Review" };
  for (const item of $input.all()) {
    const j = item.json || {};
    if (j._error || j.error) {
      const msg = (j.error && j.error.message) ? j.error.message : String(j.error || 'fetch failed');
      console.log('[normalize] SOURCE ERROR source=' + (j.source || 'unknown') + ' error=' + msg);
      out.push({ json: { source: j.source || 'unknown', error: msg, timestamp: now, _error: true } });
      continue;
    }
    const title = String(j.title || '').trim();
    const url = String(j.link || j.url || j.guid || '').trim();
    var rawUrl = url;
    var host = rawUrl.split('//').length > 1 ? rawUrl.split('//')[1].split('/')[0].toLowerCase() : '';
    var srcName = (j.source && j.source !== 'unknown') ? j.source : (hostMap[host] || host || 'unknown');
    if (!title && !url) {
      console.log('[normalize] MALFORMED item skipped (no title, no url)');
      out.push({ json: { source: srcName, error: 'malformed: missing title and url', timestamp: now, _error: true } });
      continue;
    }
    out.push({ json: {
      title: title,
      url: url,
      source: srcName,
      publishedAt: String(j.pubDate || j.published || j.updated || j.isoDate || ''),
      description: String(j.description || j.contentSnippet || j.content || j.summary || '').slice(0, 2000)
    } });
  }
  console.log('[normalize] ok=' + out.filter(o => !o.json._error).length + ' errors=' + out.filter(o => o.json._error).length);
  return out;
} catch (err) {
  console.log('[normalize] FATAL: ' + err.message);
  return [{ json: { source: 'pipeline', error: err.message, timestamp: new Date().toISOString(), _error: true } }];
}

