try {
  const RULES = [
    { cat: 'AI Models', keys: ['model', 'llm', 'gpt', 'claude', 'gemini', 'llama', 'checkpoint', 'weights', 'foundation model'] },
    { cat: 'AI Agents', keys: ['agent', 'autonomous', 'mcp', 'tool use', 'workflow automation'] },
    { cat: 'Generative AI', keys: ['image generator', 'video', 'diffusion', 'midjourney', 'sora', 'stable diffusion', 'generator'] },
    { cat: 'AI Coding', keys: ['code', 'coding', 'copilot', 'cursor', 'programmer', 'developer', 'ide'] },
    { cat: 'Robotics', keys: ['robot', 'humanoid', 'drone', 'embodied'] },
    { cat: 'AI Business', keys: ['startup', 'funding', 'billion', 'million', 'market', 'stock', 'enterprise', 'revenue'] },
    { cat: 'Research', keys: ['paper', 'arxiv', 'study', 'researchers', 'benchmark', 'dataset'] },
    { cat: 'Open Source', keys: ['open source', 'github', 'hugging face', 'apache', 'mit license'] },
    { cat: 'Regulation', keys: ['regulation', 'law', 'eu ai act', 'policy', 'copyright', 'safety', 'ban'] }
  ];
  const out = [];
  for (const item of $input.all()) {
    const j = item.json || {};
    if (j._error) { out.push({ json: j }); continue; }
    const text = ((j.title || '') + ' ' + (j.description || '')).toLowerCase();
    let best = { cat: 'Other', hits: 0 };
    const topics = [];
    for (const r of RULES) {
      let hits = 0;
      for (const k of r.keys) { if (text.includes(k)) { hits++; topics.push(k); } }
      if (hits > best.hits) { best = { cat: r.cat, hits: hits }; }
    }
    const importance = Math.min(100, 25 + best.hits * 15);
    out.push({ json: { ...j, category: best.cat, importance: importance, topics: topics.slice(0, 5), classifier: 'rules-v001 (deterministic, NOT AI-powered)' } });
  }
  console.log('[classify] classified=' + out.length);
  return out;
} catch (err) {
  console.log('[classify] FATAL: ' + err.message);
  return [{ json: { source: 'pipeline', error: err.message, timestamp: new Date().toISOString(), _error: true } }];
}

